from __future__ import annotations

import base64
from pathlib import Path
import subprocess
import tempfile
import zlib

PATCH_SHA256 = "d94cb3478f9d0112b08d55f73d295f9e35958e439636b887e23d4fe78252e062"
PATCH_B64 = ""


def main() -> None:
    import hashlib

    patch = zlib.decompress(base64.b64decode(PATCH_B64))
    actual = hashlib.sha256(patch).hexdigest()
    if actual != PATCH_SHA256:
        raise SystemExit(f"audit patch digest mismatch: {actual}")
    with tempfile.NamedTemporaryFile(suffix=".patch", delete=False) as stream:
        stream.write(patch)
        patch_path = Path(stream.name)
    try:
        if subprocess.run(["git", "apply", "--check", str(patch_path)]).returncode == 0:
            subprocess.run(["git", "apply", str(patch_path)], check=True)
        elif subprocess.run(["git", "apply", "--reverse", "--check", str(patch_path)]).returncode == 0:
            print("follow-up audit patch is already applied")
        else:
            raise SystemExit("follow-up audit patch neither applies nor matches the current tree")
    finally:
        patch_path.unlink(missing_ok=True)


if __name__ == "__main__":
    main()
